import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { collection, query, where, onSnapshot, getDoc, doc, or } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';

const ChatListPage = () => {
  const [user, setUser] = useState(null);
  const [chats, setChats] = useState([]);
  const navigate = useNavigate();
  const recipientCache = new Map();

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      const q = query(
        collection(db, 'chats'),
        or(
          where('userId', '==', user.uid),
          where('recipientId', '==', user.uid)
        )
      );

      const unsubscribe = onSnapshot(
        q,
        async (querySnapshot) => {
          const chatMap = new Map();

          await Promise.all(
            querySnapshot.docs.map(async (chatDoc) => {
              const chatData = chatDoc.data();
              const recipientId = chatData.userId === user.uid ? chatData.recipientId : chatData.userId;

              const uniqueUsers = [chatData.userId, chatData.recipientId].sort();
              const convId = `${uniqueUsers.join('_')}_${chatData.postId}`;

              let recipientEmail = recipientCache.get(recipientId);
              if (!recipientEmail) {
                try {
                  const recipientDoc = await getDoc(doc(db, 'users', recipientId));
                  recipientEmail = recipientDoc.exists() ? recipientDoc.data().email : 'Unknown';
                  recipientCache.set(recipientId, recipientEmail);
                } catch (error) {
                  console.error('Error fetching recipient email:', error);
                }
              }

              let listing = null;
              try {
                const postDoc = await getDoc(doc(db, 'posts', chatData.postId));
                listing = postDoc.exists() ? postDoc.data() : null;
              } catch (error) {
                console.error('Error fetching listing details:', error);
              }

              const existingChat = chatMap.get(convId);

              // Update or add the chat based on the latest timestamp
              if (
                !existingChat ||
                chatData.timestamp.toMillis() > existingChat.timestamp.toMillis()
              ) {
                chatMap.set(convId, {
                  id: chatDoc.id,
                  ...chatData,
                  recipientEmail,
                  listing,
                  conversationId: convId,
                  message: chatData.message, // Store the most recent message
                  timestamp: chatData.timestamp, // Keep track of the latest timestamp
                });
              }
            })
          );

          setChats(Array.from(chatMap.values()));
        },
        (error) => {
          console.error('Error fetching chats: ', error);
        }
      );

      return () => unsubscribe();
    }
  }, [user]);

  const handleChatClick = (chat) => {
    console.log("Navigating to chat with conversationId:", chat.conversationId);
    navigate(`/chat/${chat.postId}`, {
      state: { listing: chat.listing, recipientId: chat.recipientId, conversationId: chat.conversationId },
    });
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-semibold mb-4">Chats</h1>
      <div className="bg-white p-4 rounded-lg shadow-md">
        {chats.length > 0 ? (
          chats.map((chat) => (
            <div
              key={chat.conversationId}
              className="mb-2 p-2 rounded-lg bg-gray-100 cursor-pointer"
              onClick={() => handleChatClick(chat)}
            >
              <p className="text-sm font-bold">{chat.recipientEmail}</p>
              {chat.listing ? (
                <>
                  <p className="text-sm font-bold">{chat.listing.title}</p>
                  {/* Show the most recent message */}
                  <p className="text-sm text-gray-600">{chat.message}</p>
                </>
              ) : (
                <p className="text-sm text-gray-600">No listing details available</p>
              )}
            </div>
          ))
        ) : (
          <p className="text-gray-600">No chats available</p>
        )}
      </div>
    </div>
  );
};

export default ChatListPage;
